import React, { useEffect, useRef, useState, useCallback } from 'react';

interface ExamInfo {
  target_sequence: string[];
  current_target_digit: string | null;
  correct_count: number;
  total_targets: number;
  time_elapsed: number;
  running: boolean;
  feedback: string;
  exam_finished: boolean;
}

interface DetectionData {
  left_angle: number | null;
  right_angle: number | null;
  current_digit: number | null;
  sequence: string[];
  display_result: string | null;
  state: string;
  prompt_code: string | null;
  l_arm_status: string;
  r_arm_status: string;
  timer: number;
  target_person_bbox: number[] | null;
  flag_boxes: number[][];
  mode: string;
  exam_info: ExamInfo;
  cross_count: number;
  gesture_angle_threshold: number;
  gesture_cross_threshold: number;
}

const promptMessages: { [key: string]: (data: DetectionData) => string } = {
  'WAITING_FOR_PERSON': () => '偵測中，請確保您在鏡頭前方...',
  'GESTURE_START_PROMPT': () => '請舉起雙手，開始啟動手勢',
  'AWAITING_HIGH_WAVE': (data) => `請伸直雙手，向上揮過 ${data.gesture_angle_threshold}° (${data.cross_count}/${data.gesture_cross_threshold})`,
  'AWAITING_CROSS': (data) => `請交叉手腕 (${data.cross_count}/${data.gesture_cross_threshold})`,
  'AWAITING_LOW_WAVE': (data) => `請繼續向下揮動，低於 ${data.gesture_angle_threshold}° (${data.cross_count}/${data.gesture_cross_threshold})`,
  'GESTURE_COMPLETE': (data) => `手勢完成！請放下雙手以${data.state === 'IDLE' ? '開始' : '重置'}`,
  'SYSTEM_ACTION_TRIGGERED': (data) => `收到指令，系統${data.state === 'IDLE' ? '開始' : '重置'}！`,
  'PRACTICE_WAITING': () => '請將雙手垂直放下，進入準備姿勢',
  'PRACTICE_READY': () => '準備就緒，請開始比劃數字',
  'PRACTICE_DETECTING': (data) => `偵測到數字 ${data.current_digit}，請保持穩定...`,
  'PRACTICE_ARMS_NOT_STRAIGHT': () => '手臂未伸直，此次辨識無效，請重做',
  'PRACTICE_COOLDOWN': () => '成功！請放下雙手，準備下一個數字',
};

const getPromptText = (data: DetectionData | null): string => {
  if (!data || !data.prompt_code) {
    return '-';
  }
  const messageFunc = promptMessages[data.prompt_code];
  if (messageFunc) {
    return messageFunc(data);
  }
  return data.prompt_code; // Fallback to show the code if not found
};


const VideoStream: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const wsRef = useRef<WebSocket | null>(null);
  const [wsStatus, setWsStatus] = useState<string>('Connecting...');
  const [detectionData, setDetectionData] = useState<DetectionData | null>(null);
  const [currentMode, setCurrentMode] = useState<string>('practice');
  const [examTargetSequence, setExamTargetSequence] = useState<string>('1234'); // 預設考試序列
  const [backendError, setBackendError] = useState<string | null>(null); // 用於後端錯誤的新狀態
  const [isLoading, setIsLoading] = useState<boolean>(true); // 用於載入指示器的新狀態

  const sendMessage = useCallback((command: string, payload?: any) => {
    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify({ command, payload }));
    }
  }, []);

  useEffect(() => {
    setIsLoading(true); 
    const ws = new WebSocket('ws://localhost:8000/ws');
    wsRef.current = ws;

    ws.onopen = () => {
      console.log('WebSocket Connected');
      setWsStatus('Connected');
      setBackendError(null);
      sendMessage('set_mode', { mode: currentMode, target_sequence: examTargetSequence.split('') });
      sendMessage('set_video_source', { source: '0' });
      setIsLoading(false);
    };

    ws.onmessage = (event) => {
      try {
        const payload = JSON.parse(event.data);

        if (payload.error) {
          setBackendError(payload.error);
          setIsLoading(false);
          setDetectionData(null);
          const canvas = canvasRef.current;
          if (canvas) {
            const ctx = canvas.getContext('2d');
            if (ctx) {
              ctx.clearRect(0, 0, canvas.width, canvas.height);
            }
          }
          return;
        }

        if (payload.status) {
          console.log("Backend Status:", payload.status);
          setBackendError(null);
          setIsLoading(true);
          return;
        }

        setBackendError(null);
        setIsLoading(false);
        const data = payload.data;
        setDetectionData(data);

        const canvas = canvasRef.current;
        if (canvas) {
          const ctx = canvas.getContext('2d');
          if (ctx) {
            const img = new Image();
            img.onload = () => {
              canvas.width = img.width;
              canvas.height = img.height;
              ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

              if (data.flag_boxes && data.flag_boxes.length > 0) {
                ctx.strokeStyle = '#00FFFF';
                ctx.lineWidth = 2;
                data.flag_boxes.forEach((box: number[]) => {
                  ctx.strokeRect(box[0], box[1], box[2] - box[0], box[3] - box[1]);
                  ctx.fillStyle = '#00FFFF';
                  ctx.font = '16px Arial';
                  ctx.fillText('Flag', box[0] + 5, box[1] + 15);
                });
              }

              if (data.target_person_bbox) {
                ctx.strokeStyle = '#FF0000';
                ctx.lineWidth = 2;
                const bbox = data.target_person_bbox;
                ctx.strokeRect(bbox[0], bbox[1], bbox[2] - bbox[0], bbox[3] - bbox[1]);
                ctx.fillStyle = '#FF0000';
                ctx.font = '16px Arial';
                ctx.fillText('Target Person', bbox[0] + 5, bbox[1] + 15);
              }
            };
            img.src = `data:image/jpeg;base64,${payload.image}`;
          }
        }
      } catch (error) {
        console.error('Failed to parse WebSocket message:', error);
        setBackendError(`Failed to parse message from backend: ${error}`);
        setIsLoading(false);
      }
    };

    ws.onclose = () => {
      console.log('WebSocket Disconnected');
      setWsStatus('Disconnected');
      setIsLoading(false);
      setBackendError("WebSocket disconnected. Please ensure the backend server is running.");
    };

    ws.onerror = (error) => {
      console.error('WebSocket Error:', error);
      setWsStatus('Error');
      setIsLoading(false);
      setBackendError(`WebSocket error: ${error}`);
    };

    return () => {
      ws.close();
    };
  }, [sendMessage, currentMode, examTargetSequence]);

  const handleModeChange = (mode: string) => {
    setIsLoading(true);
    setCurrentMode(mode);
    sendMessage('set_mode', { mode: mode, target_sequence: examTargetSequence.split('') });
  };

  const handleStartExam = () => {
    setIsLoading(true);
    sendMessage('start_exam');
  };

  const handleStopExam = () => {
    setIsLoading(true);
    sendMessage('stop_exam');
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', padding: '20px', backgroundColor: '#282c34', color: 'white', minHeight: '100vh' }}>
      <h1>Semaphore Pose Detection System</h1>
      <p>WebSocket Status: {wsStatus}</p>

      {backendError && (
        <div style={{ color: '#FF4C6C', fontWeight: 'bold', marginBottom: '20px', border: '2px solid #FF4C6C', padding: '10px', borderRadius: '5px' }}>
          Backend Error: {backendError}
        </div>
      )}

      <div style={{ display: 'flex', flexWrap: 'wrap', justifyContent: 'center', gap: '20px', marginBottom: '20px', padding: '20px', backgroundColor: '#333', borderRadius: '8px', width: '100%', maxWidth: '1280px' }}>

        <div style={{ flex: '1 1 300px', display: 'flex', flexDirection: 'column', gap: '10px' }}>
          <h3>Mode Selection</h3>
          <div style={{ display: 'flex', gap: '10px' }}>
            <button 
              onClick={() => handleModeChange('practice')} 
              style={{ padding: '10px 20px', backgroundColor: currentMode === 'practice' ? '#007bff' : '#6c757d', color: 'white', border: 'none', borderRadius: '5px', cursor: 'pointer', flex: 1 }}
            >
              Practice Mode
            </button>
            <button 
              onClick={() => handleModeChange('exam')} 
              style={{ padding: '10px 20px', backgroundColor: currentMode === 'exam' ? '#007bff' : '#6c757d', color: 'white', border: 'none', borderRadius: '5px', cursor: 'pointer', flex: 1 }}
            >
              Exam Mode
            </button>
          </div>
        </div>

        {currentMode === 'exam' && (
          <div style={{ flex: '1 1 300px', display: 'flex', flexDirection: 'column', gap: '10px' }}>
            <h3>Exam Controls</h3>
            <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
              <label htmlFor="examSequence">Sequence:</label>
              <input 
                type="text" 
                id="examSequence" 
                value={examTargetSequence} 
                onChange={(e) => setExamTargetSequence(e.target.value)}
                style={{ padding: '8px', borderRadius: '4px', border: '1px solid #ccc', color: 'black', flex: 1 }}
              />
            </div>
            <div style={{ display: 'flex', gap: '10px' }}>
              <button 
                onClick={handleStartExam} 
                disabled={detectionData?.exam_info?.running || detectionData?.exam_info?.exam_finished}
                style={{ padding: '8px 15px', backgroundColor: '#28a745', color: 'white', border: 'none', borderRadius: '5px', cursor: 'pointer', flex: 1 }}
              >
                Start Exam
              </button>
              <button 
                onClick={handleStopExam} 
                disabled={!detectionData?.exam_info?.running && !detectionData?.exam_info?.exam_finished}
                style={{ padding: '8px 15px', backgroundColor: '#dc3545', color: 'white', border: 'none', borderRadius: '5px', cursor: 'pointer', flex: 1 }}
              >
                Stop Exam
              </button>
            </div>
          </div>
        )}
      </div>

      <div style={{ display: 'flex', gap: '20px', width: '100%', maxWidth: '1280px', justifyContent: 'center' }}>
        <div style={{ flex: 'none', maxWidth: '960px', border: '1px solid #444', borderRadius: '8px', overflow: 'hidden', position: 'relative' }}>
          {isLoading && (
            <div style={{ position: 'absolute', top: 0, left: 0, right: 0, bottom: 0, backgroundColor: 'rgba(0,0,0,0.7)', display: 'flex', justifyContent: 'center', alignItems: 'center', fontSize: '2em' }}>
              Loading Video Stream...
            </div>
          )}
          <canvas ref={canvasRef} style={{ width: '100%', height: 'auto', display: 'block' }} />
        </div>

        <div style={{ flex: 0.7, backgroundColor: '#333', padding: '10px', borderRadius: '8px', textAlign: 'left', fontSize: '0.7em' }}>
          <h2>Detection Info ({currentMode === 'practice' ? 'Practice Mode' : 'Exam Mode'})</h2>
          {detectionData ? (
            <>
              <p><strong>State:</strong> {detectionData.state}</p>
              <p><strong>Cross Count:</strong> <span style={{ color: '#FFD700', fontWeight: 'bold' }}>{detectionData.cross_count}</span></p>
              <p><strong>Prompt:</strong> <span style={{ color: '#FF4C6C' }}>{getPromptText(detectionData)}</span></p>
              <hr style={{ borderColor: '#555' }} />
              {currentMode === 'practice' && detectionData.state !== 'IDLE' && detectionData.state !== 'GESTURE_DONE' ? (
                <>
                  <p><strong>Left Angle:</strong> {detectionData.left_angle !== null ? detectionData.left_angle : 'N/A'}</p>
                  <p><strong>Right Angle:</strong> {detectionData.right_angle !== null ? detectionData.right_angle : 'N/A'}</p>
                  <p><strong>Current Digit:</strong> {detectionData.current_digit !== null ? detectionData.current_digit : 'N/A'}</p>
                  <p><strong>Sequence:</strong> {detectionData.sequence.join(' ')}</p>
                  <p><strong>Result:</strong> {detectionData.display_result !== null ? detectionData.display_result : 'N/A'}</p>
                  <p><strong>Left Arm Status:</strong> <span style={{ color: detectionData.l_arm_status === 'OK' ? '#00FF00' : '#FF4C6C' }}>{detectionData.l_arm_status}</span></p>
                  <p><strong>Right Arm Status:</strong> <span style={{ color: detectionData.r_arm_status === 'OK' ? '#00FF00' : '#FF4C6C' }}>{detectionData.r_arm_status}</span></p>
                  <p><strong>Timer:</strong> {detectionData.timer.toFixed(2)}s</p>
                </>
              ) : currentMode === 'exam' && detectionData.state !== 'IDLE' && detectionData.state !== 'GESTURE_DONE' ? (
                <>
                  <p><strong>Exam Running:</strong> {detectionData.exam_info.running ? 'Yes' : 'No'}</p>
                  <p><strong>Target Sequence:</strong> {detectionData.exam_info.target_sequence.join(' ')}</p>
                  <p><strong>Current Target:</strong> {detectionData.exam_info.current_target_digit !== null ? detectionData.exam_info.current_target_digit : 'N/A'}</p>
                  <p><strong>Correct:</strong> {detectionData.exam_info.correct_count} / {detectionData.exam_info.total_targets}</p>
                  <p><strong>Time Elapsed:</strong> {detectionData.exam_info.time_elapsed.toFixed(2)}s</p>
                  <p><strong>Feedback:</strong> <span style={{ color: detectionData.exam_info.feedback.includes('正確') ? '#00FF00' : '#FF4C6C' }}>{detectionData.exam_info.feedback}</span></p>
                  {detectionData.exam_info.exam_finished && (
                    <p style={{ color: '#00FF00', fontWeight: 'bold' }}>Exam Finished! Score: {detectionData.exam_info.correct_count} / {detectionData.exam_info.total_targets}</p>
                  )}
                </>
              ) : null}
            </>
          ) : (
            <p>Waiting for detection data...</p>
          )}
        </div>
      </div>
    </div>
  );
};

export default VideoStream;
